pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));

        // Record state before calling AdjustBetAmounts
        uint256 betBefore = c.currentBetLimit();

        // Call AdjustBetAmounts through the given caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeCall(c.AdjustBetAmounts, (amount)));

        // The rule: if the call reverted, state must be unchanged; if succeeded, betLimit must equal amount
        if (!success) {
            assertTrue(c.currentBetLimit() == betBefore);
        } else {
            assertTrue(c.currentBetLimit() == amount);
        }
    }
}

