pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 newBetLimit) public {
        // Ensure the new bet limit is reasonable (non-zero to allow wagering)
        vm.assume(newBetLimit > 0 && newBetLimit < type(uint256).max - 1);
        // Ensure the contract has enough balance to handle potential payouts (just in case)
        vm.deal(address(this), 10 ether);

        // Open to public
        c.OpenToThePublic();

        // Adjust the bet limit to newBetLimit
        c.AdjustBetAmounts(newBetLimit);

        // Test that a wager with exact newBetLimit succeeds
        vm.deal(address(0x1234), newBetLimit);
        vm.prank(address(0x1234));
        // Call wager with msg.value = newBetLimit, should not revert
        (bool success1, ) = address(c).call{value: newBetLimit}(abi.encodeWithSignature("wager()"));

        // Test that a wager with newBetLimit + 1 reverts
        vm.deal(address(0x5678), newBetLimit + 1);
        vm.prank(address(0x5678));
        (bool success2, ) = address(c).call{value: newBetLimit + 1}(abi.encodeWithSignature("wager()"));

        // The rule: exactly newBetLimit should succeed, newBetLimit+1 should fail
        assertTrue(success1 && !success2);
    }
}

