        bool success = address(c).call{value: newBetLimit}(abi.encodeWithSignature("wager()"));
        // Assert that the call succeeded (no revert) and that the wager mapping reflects the sent amount
        // Since wagers is private, we use the public getter hasPlayerWagered and the successful call
        assertTrue(success, "Wager should succeed");
    }
}

