pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // Ensure amount is non-zero so donate() has an effect
        vm.assume(amount > 0);
        // Also ensure amount is not too large (to avoid overflow or out-of-gas)
        vm.assume(amount < 1e30);

        // Make the contract open to public (required for donate)
        c.OpenToThePublic();

        // Call AdjustBetAmounts as owner
        c.AdjustBetAmounts(amount);

        // Get initial totalDonated (public getter)
        uint256 initialDonated;
        // totalDonated is public so we can read it via the auto-generated getter
        // Solidity auto-generates a getter for public state variables
        // But note: totalDonated is uint256, so the getter is totalDonated()
        // However, it's not directly accessible as c.totalDonated() because it's a mapping? No, it's just uint256 public totalDonated
        // The getter should be callable. But careful: the contract declares it as uint256 totalDonated; (no public keyword)
        // Wait: the contract has: uint256 totalDonated; (no visibility - defaults to private? Actually in Solidity, state variables without explicit visibility default to internal, not public)
        // So it's not directly readable. But the problem says we should observe through public/external surface - we need another way.
        // Let's read it via the donated amount: we can track it by checking eth balance changes or using the emit Donate event?
        // Actually the requirement says we can use public/external view functions. There is no getter for totalDonated.
        // We need to find a general rule that only uses available public/external functions.
        // The available public/external functions: ethBalance(), currentDifficulty(), currentBetLimit(), hasPlayerWagered(), winnersPot(), donate() (payable), wager() (payable), play(), OpenToThePublic(), AdjustBetAmounts(), AdjustDifficulty(), transferAnyERC20Token().
        // We need a rule that P satisfies and M breaks. The difference is that donate() in P calls donateToWhale which increases totalDonated and transfers eth to whale. In M it does nothing.
        // So after a call to AdjustBetAmounts, calling donate() should change the contract's eth balance (since whale is address(this) in setUp? Actually whale is address(this) so donation returns eth to this contract? No, address(this) is the test contract. So donate sends eth to the test contract - that doesn't change eth balance of C. 
        // Better: use ethBalance() - after donate(), ethBalance should decrease because it sends half the balance? No, donateToWhale sends msg.value to whale, so C's balance decreases by msg.value.
        // So rule: after AdjustBetAmounts, calling donate() with value should decrease ethBalance by that value (assuming contract has enough balance).
        // But we need to fund the contract first.
        vm.deal(address(c), amount * 2);

        uint256 balanceBefore = c.ethBalance();
        // Call donate with value
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("donate()"));
        require(success, "donate failed");
        uint256 balanceAfter = c.ethBalance();
        assertTrue(balanceBefore - balanceAfter == amount);
    }
}

