        // Ensure the contract is open to public for subsequent operations
        if (!c.isOpenToPublic()) {
            c.OpenToThePublic();
        }
        // Call AdjustBetAmounts as part of the sequence
        c.AdjustBetAmounts(adjustAmount);
        // Record totalDonated before donate
        uint256 beforeTotal = c.totalDonated();
