        (bool success, ) = address(c).call{value: value}(abi.encodeWithSignature("donate()"));
        // The invariant: after AdjustBetAmounts, donate does nothing; totalDonated must not change
        assertTrue(c.totalDonated() == beforeTotal);
    }
