    function testFuzz_property(uint256 newBetLimit) public {
        vm.deal(address(c), 100 ether);
        uint256 winnersPotBefore = c.winnersPot();
        uint256 balanceBefore = address(c).balance;
        c.AdjustBetAmounts(newBetLimit);
        uint256 winnersPotAfter = c.winnersPot();
        uint256 balanceAfter = address(c).balance;
        assertTrue(winnersPotBefore * balanceAfter == winnersPotAfter * balanceBefore);
    }
}
